/**
 * GET /api/unsubscribe?token=<signed-token>
 *
 * Handles one-click unsubscribe links embedded in newsletter emails.
 * The token is an HMAC-SHA256 signed payload: base64url(JSON({email, exp})).sig
 * Generated by newsletter-engine.ts at send-time per subscriber.
 *
 * On success: sets status='unsubscribed' in Supabase, redirects to /unsubscribe?success=1
 * On failure: redirects to /unsubscribe?error=1
 *
 * Token generation/verification logic lives in src/lib/unsubscribe.ts —
 * Next.js App Router forbids non-handler named exports from route.ts files.
 */

import { NextRequest, NextResponse } from 'next/server';
import { supabaseAdmin } from '@/lib/supabase';
import { ENV } from '@/lib/env';
import { verifyUnsubscribeToken } from '@/lib/unsubscribe';

export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const token = searchParams.get('token') || '';

  const siteUrl = ENV.SITE_URL;
  const errorUrl = `${siteUrl}/unsubscribe?error=1`;
  const successUrl = `${siteUrl}/unsubscribe?success=1`;

  if (!token) {
    return NextResponse.redirect(errorUrl);
  }

  const email = verifyUnsubscribeToken(token);
  if (!email) {
    return NextResponse.redirect(errorUrl);
  }

  if (!supabaseAdmin) {
    return NextResponse.redirect(errorUrl);
  }

  const { error } = await supabaseAdmin
    .from('newsletter_subscribers')
    .update({ status: 'unsubscribed', updated_at: new Date().toISOString() })
    .eq('email', email.toLowerCase().trim());

  if (error) {
    console.error('[Unsubscribe] DB error:', error.message);
    return NextResponse.redirect(errorUrl);
  }

  console.log('[Unsubscribe] Successfully unsubscribed');
  return NextResponse.redirect(successUrl);
}

// Support POST for RFC 8058 one-click List-Unsubscribe-Post
export async function POST(req: NextRequest) {
  // RFC 8058 sends: Content-Type: application/x-www-form-urlencoded
  // Body: List-Unsubscribe=One-Click
  // Token is in the URL query param
  return GET(req);
}
